<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {use} from 'echarts/core';
import {LineChart} from 'echarts/charts';
import {GridComponent,LegendComponent,TooltipComponent} from 'echarts/components';
import {CanvasRenderer} from 'echarts/renderers';
import VChart from 'vue-echarts';
import {useRoute} from 'vue-router';
import {cycleStage} from '../api/management';
import {deadlineText,growthChart,percent,type CockpitData} from '../lib/cockpit';
import CockpitIcon from './CockpitIcon.vue';
use([LineChart,GridComponent,LegendComponent,TooltipComponent,CanvasRenderer]);
const route=useRoute(),data=ref<CockpitData|null>(null),cycleId=ref(''),periods=ref(6),loading=ref(false),error=ref(''),showAll=ref(false),now=ref(Date.now());
let controller:AbortController|undefined,timer:ReturnType<typeof setInterval>|undefined;
const cycle=computed(()=>data.value?.cycle),permissions=computed(()=>new Set(data.value?.permissions??[]));
const allowed=(cap:string)=>permissions.value.has(cap);
const todos=computed(()=>data.value?.todos.filter(t=>allowed(t.capability))??[]);
const pending=computed(()=>todos.value.reduce((n,t)=>n+t.count,0));
const ready=computed(()=>todos.value.find(t=>t.key==='publication')?.count);
const departments=computed(()=>showAll.value?data.value?.departments??[]:data.value?.departments.slice(0,5)??[]);
const chart=computed(()=>growthChart(data.value?.trend??[]));
const stats=computed(()=>cycle.value?[
 {label:'参评人数',value:String(cycle.value.participants),note:'当前周期有效参评成员',icon:'people',tone:'blue'},
 {label:'材料提交率',value:percent(cycle.value.materialRate),note:`${cycle.value.materials} / ${cycle.value.participants} 人`,rate:cycle.value.materialRate,icon:'document',tone:'blue'},
 {label:'自评完成率',value:percent(cycle.value.selfRate),note:`${cycle.value.self_submitted} / ${cycle.value.participants} 人`,rate:cycle.value.selfRate,icon:'edit',tone:'teal'},
 {label:'他评完成率',value:percent(cycle.value.peerRate),note:`${cycle.value.peer_submitted} / ${cycle.value.peer_expected} 项任务`,rate:cycle.value.peerRate,icon:'people',tone:'purple'},
 {label:'待处理事项',value:String(pending.value),note:'核验、确认、申诉及发布',icon:'alert',tone:'orange'},
 {label:'待发布结果',value:ready.value===undefined?'—':String(ready.value),note:allowed('result.publish')?'已确认且满足发布条件':'暂无发布权限',icon:'layers',tone:'red'},
]:[]);
const shortcuts=[{label:'周期与分配',icon:'cycle',to:'/management/monthly?tab=cycles',cap:'cycle.manage'},
 {label:'评价规则',icon:'rules',to:'/management/rules',cap:'org.manage'},
 {label:'组织与权限',icon:'org',to:'/management/settings?tab=roles',cap:'org.manage'},
 {label:'月评档案',icon:'chat',to:'/management/archives?tab=cycles',cap:'result.read_published'},
 {label:'用户管理',icon:'people',to:'/management/settings?tab=users',cap:'org.manage'},
 {label:'操作日志',icon:'log',to:'/management/settings?tab=audit',cap:'org.manage'}];
const date=(v:string|null|undefined)=>v?new Date(v).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}):'尚未设置';
function target(to:string){const u=new URL(to,'http://local');if(cycleId.value)u.searchParams.set('cycleId',cycleId.value);return u.pathname+u.search;}
async function load(){
 controller?.abort();const request=new AbortController();controller=request;loading.value=true;error.value='';
 const query=new URLSearchParams({periods:String(periods.value)});if(cycleId.value)query.set('cycleId',cycleId.value);
 try{const response=await fetch('/api/v1/management/cockpit?'+query,{credentials:'include',signal:request.signal});
  const json=await response.json();if(!response.ok)throw new Error(response.status===403?'当前账号没有查看此工作台的权限':response.status===404?'该周期不存在或不在授权范围内':`工作台加载失败（${response.status}）`);
  if(controller!==request)return;data.value=json.data;cycleId.value=json.data.cycle?.id??'';
 }catch(e){if(request.signal.aborted)return;data.value=null;error.value=e instanceof Error?e.message:'网络连接异常，请重试';}
 finally{if(controller===request)loading.value=false;}
}
watch(periods,()=>void load());
onMounted(()=>{cycleId.value=typeof route.query.cycleId==='string'?route.query.cycleId:'';void load();timer=setInterval(()=>now.value=Date.now(),60000);});
onBeforeUnmount(()=>{controller?.abort();if(timer)clearInterval(timer);});
</script>
<template>
 <div class="cockpit" :aria-busy="loading">
  <header class="intro"><div><h1>管理工作台</h1><p>组织级评价管理驾驶舱 · 全局掌握月评进度、异常事项与组织成长</p></div><div class="cycle-picker"><label class="sr-only" for="cockpit-cycle">当前评价周期</label><select id="cockpit-cycle" v-model="cycleId" :disabled="!data?.cycles.length" @change="showAll=false;load()"><option v-for="c in data?.cycles??[]" :key="c.id" :value="c.id">{{c.title}} · {{c.month}}</option></select><span v-if="cycle" class="status">{{cycleStage(cycle.status)}}</span></div></header>
  <div v-if="error" class="surface empty" role="alert"><p>{{error}}</p><button class="btn" @click="load">重新加载</button></div>
  <p v-else-if="loading&&!data" class="surface empty" role="status">正在加载评价数据…</p>
  <div v-else-if="!cycle" class="surface empty">暂无可查看的评价周期</div>
  <template v-else>
   <div v-if="loading" class="refresh" role="status">正在更新当前周期数据…</div>
   <section class="surface cycle-overview"><div class="cycle-name"><CockpitIcon name="cycle"/><div><span>当前评价周期</span><strong>{{cycle.month}}</strong></div></div><div class="cycle-dates">{{date(cycle.open_at)}} — {{date(cycle.close_at)}}</div><div class="overall"><span>整体评价进度 <small>自评与他评有效任务</small></span><div><progress v-if="cycle.overallRate!=null" :value="cycle.overallRate" max="1" aria-label="整体评价进度"/><strong>{{percent(cycle.overallRate)}}</strong></div></div><div class="countdown">{{deadlineText(cycle,now)}}</div></section>
   <div class="metrics"><section v-for="s in stats" :key="s.label" class="surface metric" :class="s.tone"><span class="icon-tile"><CockpitIcon :name="s.icon"/></span><div><h2>{{s.label}}</h2><strong>{{s.value}}</strong><progress v-if="s.rate!=null" :value="s.rate" max="1" :aria-label="s.label"/><small>{{s.note}}</small></div></section></div>
   <div class="content-grid">
    <section class="surface department-panel"><div class="section-head"><h2><CockpitIcon name="chart"/>各部门评价进度</h2><button class="text-button" @click="showAll=!showAll">{{showAll?'收起部门':'查看全部部门'}} →</button></div><div class="table-wrap"><table><thead><tr><th>部门名称</th><th>评价完成率</th><th>已完成 / 应完成</th></tr></thead><tbody><tr v-for="d in departments" :key="d.id??'none'"><td><RouterLink v-if="d.id" :to="{path:'/department/progress',query:{cycleId:cycle.id,departmentId:d.id}}">{{d.name}}</RouterLink><span v-else>{{d.name}}</span></td><td><div class="department-rate"><progress v-if="d.rate!=null" :value="d.rate" max="1" :aria-label="d.name+'评价完成率'"/><span>{{percent(d.rate)}}</span></div></td><td>{{d.done}} / {{d.expected}}</td></tr></tbody></table></div><p v-if="!departments.length" class="empty">当前授权范围暂无有效参评成员</p><p class="footnote">按部门成员的有效自评任务与收到的有效他评任务合计。</p></section>
    <section class="surface todo-panel"><div class="section-head"><h2><CockpitIcon name="check"/>待处理事项</h2><small>本周期 · 有权处理</small></div><div class="todo-list"><RouterLink v-for="t in todos" :key="t.key" :to="target(t.to)" class="todo-row"><span class="todo-icon" :class="t.key"><CockpitIcon :name="({calibration:'alert',confirmation:'check',feedback:'chat',publication:'send'} as Record<string,string>)[t.key]"/></span><span>{{t.label}}</span><span class="count" :class="{idle:t.count===0}">{{t.count===0?'暂无待办':t.count}}</span><span>›</span></RouterLink></div><p v-if="!todos.length" class="empty">当前账号暂无可处理事项</p></section>
    <section class="surface trend-panel"><div class="section-head"><h2><CockpitIcon name="chart"/>组织成长趋势</h2><select v-model="periods" aria-label="趋势时间范围"><option :value="3">近3个周期</option><option :value="6">近6个周期</option><option :value="12">近12个周期</option></select></div><p class="chart-note">授权范围内正式发布的维度汇总 · 每人取最新有效发布版本</p><VChart v-if="data?.trend.length" :option="chart" autoresize class="growth-chart" aria-label="正式发布的评价维度历史趋势"/><div v-else class="chart-empty">{{allowed('result.read_published')?'暂无满足汇总条件的已发布维度数据':'暂无已发布结果查看权限'}}</div><p class="footnote">缺失数据保留为空；每个维度至少有三份有效发布结果才显示汇总。</p></section>
    <section class="surface shortcuts-panel"><div class="section-head"><h2><CockpitIcon name="rules"/>快捷管理入口</h2></div><div class="shortcuts"><template v-for="s in shortcuts" :key="s.label"><RouterLink v-if="allowed(s.cap)" :to="target(s.to)"><CockpitIcon :name="s.icon"/><span>{{s.label}}</span></RouterLink><div v-else class="shortcut-disabled" :title="'当前账号暂无'+s.label+'权限'"><CockpitIcon :name="s.icon"/><span>{{s.label}}</span><small>暂无权限</small></div></template></div></section>
   </div>
  </template>
 </div>
</template>
<style scoped>
