rid;place-items:center;flex-shrink:0}.icon-tile svg{width:23px;height:23px}.metric h2{font-size:12px;font-weight:500;margin:0;color:#5d708c;line-height:1.5}.metric strong{font-size:28px;display:block;line-height:1.4;margin:6px 0;color:var(--accent)}.metric:first-child strong{color:#172b4d}.metric small{font-size:10px;color:#8190a5;display:block;line-height:1.6}.metric progress{height:4px;margin-bottom:4px;accent-color:var(--accent)}.content-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(0,1fr);gap:18px;align-items:stretch}.content-grid>.surface{padding:21px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.section-head h2{font-size:17px;display:flex;gap:10px;align-items:center;margin:0;line-height:1.5}.section-head h2 svg{width:21px;height:21px;color:#246bfd}.trend-panel .section-head select{width:128px;flex:0 0 128px}.section-head small{font-size:11px;color:#8190a5}.text-button{background:none;border:0;color:#246bfd;font-size:12px;cursor:pointer;white-space:nowrap;padding:5px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th{background:#f5f8fc;color:#78889d;font-weight:500;text-align:left;padding:11px 8px}td{padding:15px 8px;border-bottom:1px solid #f0f3f8}td:first-child{width:24%;font-weight:600}td:last-child{text-align:right;white-space:nowrap}td a{color:#233e62;text-decoration:none}tr:hover td{background:#f8fbff}.department-rate{display:flex;gap:12px;align-items:center}.department-rate span{width:39px;text-align:right;flex-shrink:0}progress{appearance:none;width:100%;height:8px;border:0;border-radius:8px;overflow:hidden;background:#edf1f7;accent-color:#246bfd}progress::-webkit-progress-bar{background:#edf1f7;border-radius:8px}progress::-webkit-progress-value{background:var(--accent,#246bfd);border-radius:8px}progress::-moz-progress-bar{background:var(--accent,#246bfd);border-radius:8px}.todo-list{display:grid;gap:9px}.todo-row{display:flex;align-items:center;gap:11px;text-decoration:none;color:#253f60;font-size:13px;padding:10px 12px;background:#f8faff;border-radius:7px}.todo-row:hover{background:#edf4ff}.todo-icon{color:#246bfd;display:flex}.todo-icon svg{width:21px;height:21px}.todo-icon.calibration{color:#e75a64}.todo-icon.confirmation{color:#8754de}.todo-icon.publication{color:#7863e7}.count{margin-left:auto;color:#d65461;background:#ffedf0;border-radius:20px;padding:2px 8px;font-size:11px}.count.idle{background:#edf3fa;color:#8390a2}.chart-note,.footnote{font-size:11px;color:#8492a6;line-height:1.7;margin:0 0 12px}.footnote{margin:10px 0 0}.growth-chart{height:232px;width:100%}.chart-empty{height:232px;display:grid;place-items:center;color:#8c9aaf;font-size:13px;background:#fbfcfe;border-radius:8px}.shortcuts-panel{display:flex;flex-direction:column}.shortcuts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(2,minmax(90px,1fr));gap:12px;flex:1}.shortcuts a,.shortcut-disabled{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:9px;background:#f6f9fe;border-radius:9px;text-decoration:none;color:#29466c;font-size:12px;text-align:center;padding:10px 4px}.shortcuts a:hover{background:#eaf2ff;color:#246bfd}.shortcuts svg{width:25px;height:25px;color:#246bfd}.shortcut-disabled{opacity:.5}.shortcut-disabled small{font-size:10px}.empty{padding:35px;text-align:center;color:#7e8da3;font-size:13px}.refresh{font-size:11px;color:#246bfd;margin-bottom:8px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:1350px){.intro{align-items:flex-start}.cycle-picker{flex-direction:column;align-items:flex-end}.cycle-overview{gap:18px;flex-wrap:wrap}.cycle-dates{padding-left:18px}.overall{min-width:200px}.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.metric{min-height:105px}.content-grid{grid-template-columns:minmax(0,1.45fr) minmax(0,1fr)}}
@media(max-width:960px){.content-grid{grid-template-columns:1fr}.department-panel{order:0}.todo-panel{order:1}.trend-panel{order:2}.shortcuts-panel{order:3}.intro{flex-direction:column;gap:14px}.cycle-picker{flex-direction:row;align-items:center}.cycle-dates{border:0;padding:0}.cycle-overview{padding:20px}.countdown{white-space:normal}}
@media(max-width:560px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.metric{padding:14px 10px;gap:8px}.metric strong{font-size:25px}.icon-tile{width:29px;height:34px}.icon-tile svg{width:20px}.cycle-picker{flex-wrap:wrap;width:100%}.cockpit select{max-width:100%}.cycle-overview{gap:14px}.cycle-dates{width:100%}.overall{min-width:100%;flex:auto}.content-grid>.surface{padding:16px}.section-head h2{font-size:15px}.shortcuts{gap:8px}.intro h1{font-size:26px}}
